public class MainForm : Form
{
    public MainForm()
    {
        Text = "SHADOW CLIENT";
        Size = new Size(430, 550);
        StartPosition = FormStartPosition.CenterScreen;
        BackColor = Color.FromArgb(10, 12, 19);
        ForeColor = Color.White;
        FormBorderStyle = FormBorderStyle.FixedSingle;
        MaximizeBox = false;

        Label title = new Label()
        {
            Text = "SHADOW CLIENT",
            Font = new Font("Segoe UI", 22,
                FontStyle.Bold),
            ForeColor = Color.FromArgb(255, 45, 65),
            Location = new Point(25, 25),
            AutoSize = true
        };
        Controls.Add(title);

        Label subtitle = new Label()
        {
            Text = "GAMING CONTROL PANEL  |  V1.0",
            ForeColor = Color.Gray,
            Font = new Font("Segoe UI", 9),
            Location = new Point(28, 65),
            AutoSize = true
        };
        Controls.Add(subtitle);

        AddModule("ES", "ES Module", 125);
        AddModule("AIM", "Aim Module", 225);
        AddModule("FL", "FL Module", 325);

        Label footer = new Label()
        {
            Text = "SHADOW CLIENT  •  READY",
            ForeColor = Color.Gray,
            Font = new Font("Segoe UI", 9),
            AutoSize = true,
            Location = new Point(100, 445)
        };
        Controls.Add(footer);
    }

    void AddModule(string name, string description,
        int y)
    {
        Panel card = new Panel()
        {
            Location = new Point(25, y),
            Size = new Size(365, 75),
            BackColor = Color.FromArgb(25, 28, 39)
        };

        Label module = new Label()
        {
            Text = name,
            Font = new Font("Segoe UI", 15,
                FontStyle.Bold),
            ForeColor = Color.White,
            Location = new Point(15, 10),
            AutoSize = true
        };

        Label info = new Label()
        {
            Text = description,
            Font = new Font("Segoe UI", 9),
            ForeColor = Color.Gray,
            Location = new Point(17, 43),
            AutoSize = true
        };

        CheckBox toggle = new CheckBox()
        {
            Appearance = Appearance.Button,
            Text = "OFF",
            TextAlign = ContentAlignment.MiddleCenter,
            Font = new Font("Segoe UI", 10,
                FontStyle.Bold),
            ForeColor = Color.White,
            BackColor = Color.FromArgb(65, 68, 80),
            FlatStyle = FlatStyle.Flat,
            Location = new Point(275, 20),
            Size = new Size(70, 35),
            Cursor = Cursors.Hand
        };

        toggle.FlatAppearance.BorderSize = 0;

        toggle.CheckedChanged += (s, e) =>
        {
            toggle.Text = toggle.Checked ? "ON" : "OFF";

            toggle.BackColor = toggle.Checked
                ? Color.FromArgb(220, 35, 55)
                : Color.FromArgb(65, 68, 80);
        };

        card.Controls.Add(module);
        card.Controls.Add(info);
        card.Controls.Add(toggle);

        Controls.Add(card);
    }
}

